class Base:
    def size(self):
        return 1
class Counter(Base):
    def __init__(self, value):
        self.value = value
    def sub(self, delta):
        if delta > self.value:
            raise NegativeError('neg')
        return self.value - delta
class CounterError(ValueError):
    pass
class NegativeError(CounterError):
    pass
